// Copies chunks from an async source into a sink.
export async function pump(source, sink, opts = {}) {
  const signal = opts.signal;
  let written = 0;

  const withSignal = (promise) => {
    if (!signal) return promise;
    if (signal.aborted) {
      // prevent unhandled rejection if the original promise later rejects
      promise.catch(() => {});
      return Promise.reject(signal.reason);
    }
    let onAbort;
    const abortPromise = new Promise((_, reject) => {
      onAbort = () => reject(signal.reason);
      signal.addEventListener('abort', onAbort);
    });
    // prevent unhandled rejection when abort wins first
    promise.catch(() => {});
    return Promise.race([promise, abortPromise]).finally(() => {
      signal.removeEventListener('abort', onAbort);
    });
  };

  const callNext = () => {
    try {
      return source.next();
    } catch (e) {
      return Promise.reject(e);
    }
  };

  const callWrite = (value) => {
    try {
      return sink.write(value);
    } catch (e) {
      return Promise.reject(e);
    }
  };

  const callReturn = () => {
    try {
      return source.return();
    } catch (e) {
      return Promise.reject(e);
    }
  };

  const callAbort = (err) => {
    try {
      return sink.abort(err);
    } catch (e) {
      return Promise.reject(e);
    }
  };

  try {
    while (true) {
      if (signal?.aborted) {
        throw signal.reason;
      }

      const result = await withSignal(callNext());

      if (result.done) break;

      if (signal?.aborted) {
        throw signal.reason;
      }

      await withSignal(callWrite(result.value));
      written++;
    }

    if (signal?.aborted) {
      throw signal.reason;
    }

    await sink.close();
    return { written };
  } catch (err) {
    try {
      await callReturn();
    } catch (_) {}
    try {
      await callAbort(err);
    } catch (_) {}
    throw err;
  }
}

