// Copies chunks from an async source into a sink.
export async function pump(source, sink, opts = {}) {
  const signal = opts.signal;
  let written = 0;

  // Already-aborted fast path: no read/write, cleanup and reject with reason
  if (signal?.aborted) {
    const err = signal.reason;
    try { await source.return(); } catch {}
    try { await sink.abort(err); } catch {}
    throw err;
  }

  let abortListener;
  let abortPromise;
  if (signal) {
    abortPromise = new Promise((_, reject) => {
      abortListener = () => reject(signal.reason);
      signal.addEventListener('abort', abortListener);
    });
  }

  const cleanupListener = () => {
    if (signal && abortListener) {
      signal.removeEventListener('abort', abortListener);
    }
  };

  async function fail(originalErr) {
    cleanupListener();
    try { await source.return(); } catch {}
    try { await sink.abort(originalErr); } catch {}
    throw originalErr;
  }

  try {
    while (true) {
      let res;
      try {
        res = signal
          ? await Promise.race([source.next(), abortPromise])
          : await source.next();
      } catch (e) {
        if (signal?.aborted) {
          await fail(signal.reason);
        } else {
          await fail(e);
        }
      }

      if (signal?.aborted) {
        await fail(signal.reason);
      }

      const { done, value } = res;
      if (done) break;

      try {
        if (signal) {
          await Promise.race([sink.write(value), abortPromise]);
        } else {
          await sink.write(value);
        }
      } catch (e) {
        if (signal?.aborted) {
          await fail(signal.reason);
        } else {
          await fail(e);
        }
      }

      if (signal?.aborted) {
        await fail(signal.reason);
      }

      written++;
    }
  } catch (e) {
    // e is the original error thrown by fail()
    throw e;
  }

  if (signal?.aborted) {
    await fail(signal.reason);
  }

  cleanupListener();

  try {
    await sink.close();
  } catch (closeErr) {
    // If close itself fails, attempt to return source but do not call abort
    // to keep close-once / abort-never for the success path attempt.
    try { await source.return(); } catch {}
    throw closeErr;
  }

  return { written };
}

